            cells=set(comp)
            visited=set()
            for r,c in sorted(comp):
                if (r,c) in visited: continue
                seg=[(r,c)]; visited.add((r,c))
                rr,cc=r+dr,c+dc
                while (rr,cc) in cells:
                    seg.append((rr,cc)); visited.add((rr,cc)); rr+=dr; cc+=dc
